void Solver::bump_var(int var, double coeff) {
    // Use a non-linear bump: scale coeff by a factor based on current activity
    // to give extra boost to recently conflicting variables
    double boost = coeff * (1.0 + 0.1 * (activity[var] / (var_inc + 1e-300)));
    if (boost > 2.0) boost = 2.0; // cap the boost to avoid runaway scores
    if ((activity[var] += var_inc * boost) > 1e100) {
        for (int i = 1; i <= vars; i++) activity[i] *= 1e-100;
        var_inc *= 1e-100;
    }
    if (vsids.inHeap(var)) vsids.update(var);
}
